mapper.select:
select  distinct t2.*,
t3.translate as english,t3.translate_state as englishTranslateState,t3.public_state as englishPublicState,
t6.translate as russian,t6.translate_state as russianTranslateState,t6.public_state as russianPublicState,
t4.translate as french,t4.translate_state as frenchTranslateState,t4.public_state as frenchPublicState,
t5.translate as spanish,t5.translate_state as spanishTranslateState,t5.public_state as spanishPublicState
 from ( t_product_relation t1  right join  t_entry_info t2 on t1.entry_id = t2.id)
left JOIN t_translate t3 ON t2.en_trans_id = t3.id
left JOIN t_translate t6 ON t2.ru_trans_id = t6.id
left JOIN t_translate t4 ON t2.fra_trans_id = t4.id
left JOIN t_translate t5 ON t2.spa_trans_id = t5.id
where  t2.is_delete = 0

   and t1.version_id = #{entryInfoEntity.versionID,jdbcType=VARCHAR}


    and t1.task_id = #{entryInfoEntity.taskId,jdbcType=VARCHAR}


    and t1.product_id = #{entryInfoEntity.productID,jdbcType=VARCHAR}


    and t2.classfy1 = #{entryInfoEntity.classfy1,jdbcType=VARCHAR}


    and t2.classfy2 = #{entryInfoEntity.classfy2,jdbcType=VARCHAR}



    and t2.entry = #{entryInfoEntity.entry,jdbcType=VARCHAR}


    and t2.abbr = #{entryInfoEntity.abbr,jdbcType=VARCHAR}


    and t2.entry_state = #{entryInfoEntity.entryState,jdbcType=INTEGER}


    and t2.entry_label like CONCAT('%',#{entryInfoEntity.entryLabel,jdbcType=VARCHAR},'%')


    and t2.tag like CONCAT('%',#{entryInfoEntity.tag,jdbcType=VARCHAR},'%')


